(() => {'use strict';const RF=window.RF,api=RF.Systems?.Encounters;if(!api)throw new Error('Canonical Encounters missing before V11.25 extension.');const extra={"v4-nearby-enemies-ui":"RF.UI.nearbyEnemies=function(s){let list=RF.refreshEncounters(s);if(!RF.fieldTables[s.location])return'';return `<section class=\"card\"><div class=\"questTitle\"><h3>Nearby Creatures</h3><span class=\"tag\">WILD AREA</span></div><div class=\"sub\">You can choose your fights here. Aggressive creatures may still ambush you while travelling or waiting.</div><div class=\"list\" style=\"margin-top:9px\">${list.length?list.map(x=>{let e=RF.DATA.enemies[x.id],seen=s.collection.enemies[x.id]>0;return `<div class=\"row enemyRow\"><div class=\"icon\">${e.icon}</div><div class=\"meta\"><b>${seen?e.name:'Unknown '+e.icon} • Lv ${e.level}</b><small>${e.temperament||'Hostile'} • ${seen?`${s.collection.enemies[x.id]} defeated`:'Not yet recorded'}</small></div><button data-fight=\"${x.uid}\" ${s.activity||s.combat?'disabled':''}>Fight</button></div>`}).join(''):'<div class=\"sub\">The area is unusually quiet.</div>'}</div></section>`};\n"};const prior=api.installHistoricalFragment.bind(api);const installed=api.installedFragments||[];const done=new Set(installed);function run(src,name){const script=document.createElement('script');script.type='text/javascript';script.setAttribute('data-rf-canonical-encounter-fragment',name);script.textContent=src+'\n//# sourceURL=realmforge-canonical:///systems.encounters/fragment/'+name+'\n';(document.head||document.documentElement).appendChild(script);script.remove();}api.installHistoricalFragment=function(name){if(done.has(name))return false;if(Object.prototype.hasOwnProperty.call(extra,name)){run(extra[name],name);done.add(name);installed.push(name);return true;}return prior(name);};const prevNames=typeof api.fragmentNames==='function'?api.fragmentNames.bind(api):()=>[];api.fragmentNames=()=>[...prevNames(),...Object.keys(extra)];})();
