  RF.Systems.Gathering=RF.Modules.register('systems.gathering',api,{owner:'systems',status:'canonical',foundation:'systems.fieldcraft',historicalFragmentCount:Object.keys(fragmentSources).length,extractedIn:'11.15.0',extendedIn:'11.17.0'});
