  const RF=window.RF,api=RF.Systems.Combat;if(!api)throw new Error('Combat canonical owner missing before V11.23 fragment extension.');
  const extraSources={"v3-combat-techniques":"const v3Combat=RF.combatAction;RF.combatAction=function(action){let s=RF.state,e=s.combat;if(!e)return;\n  if(action==='power'){let cost=Math.max(10,20-RF.perkRank(s,'brutal_training')*3);if(s.player.stamina<cost){RF.log(s,'Not enough stamina for Power Strike.','bad');RF.UI.render(s);return}s.player.stamina-=cost;let d=RF.DATA.enemies[e.id],mult=1.65+RF.perkRank(s,'brutal_training')*.18;if(Math.random()<.78){let hit=Math.max(1,Math.round((5+RF.weaponDamage(s)+s.skills.strength.level)*(mult)*(0.88+Math.random()*.25)-d.armor*.35));e.hp-=hit;RF.log(s,`Power Strike crashes into ${d.name} for ${hit}.`,'good');RF.addXp(s,'strength',14)}else RF.log(s,'Your Power Strike whistles past.','bad');if(e.hp<=0)return RF.winCombat();RF.enemyTurn();RF.save(s);RF.UI.render(s);return}\n  if(action==='precision'){let cost=14;if(s.player.stamina<cost){RF.log(s,'Not enough stamina for Precise Strike.','bad');RF.UI.render(s);return}s.player.stamina-=cost;let d=RF.DATA.enemies[e.id],crit=Math.random()<(.18+s.skills.attack.level*.006),hit=Math.max(1,Math.round((5+RF.weaponDamage(s)+s.skills.attack.level*.9)*(crit?1.75:1.15)-d.armor*.25));e.hp-=hit;RF.log(s,`${crit?'Critical! ':''}Precise Strike deals ${hit}.`,'good');RF.addXp(s,'attack',12);if(e.hp<=0)return RF.winCombat();RF.enemyTurn();RF.save(s);RF.UI.render(s);return}\n  if(action==='smoke'&&RF.perkRank(s,'vanish')&&RF.takeItem(s,'smoke_bomb',1)){let boss=['captain_voss','gravewarden'].includes(e.id);if(!boss){RF.log(s,'Smoke floods the fight. You vanish before your enemy can react.','good');s.combat=null;RF.save(s);RF.UI.render(s);return}RF.log(s,'The boss refuses to lose you in the smoke.','bad')}\n  return v3Combat(action)\n};\n","v3-combat-win-perks":"const v3Win=RF.winCombat;RF.winCombat=function(){let s=RF.state,id=s.combat?.id;if(!id)return;let enemy=RF.DATA.enemies[id];let scav=RF.perkRank(s,'scavenger');if(scav&&enemy?.drops)enemy.drops.forEach(([drop,ch,q])=>{if(Math.random()<ch*.12*scav){RF.addItem(s,drop,q);RF.log(s,`Scavenger finds extra ${RF.DATA.items[drop]?.name||drop}.`,'good')}});v3Win();s=RF.state;\n  if(id==='gravewarden'){s.dungeons.crypt.cleared=true;s.stats.dungeonsCleared++;s.flags.gravewardenDefeated=true;s.reputation.greenvale+=3;RF.log(s,'The Forgotten Crypt falls silent. For the first time, the cold air begins to warm.','important')}\n  if(id==='ridge_raider')s.reputation.ironridge+=1;\n  RF.questCheck(s);RF.save(s)\n};\n","v3-combat-ui":"RF.UI.combat=function(s){let e=s.combat,enemy=RF.DATA.enemies[e.id],smoke=RF.perkRank(s,'vanish')&&(s.inventory.smoke_bomb||0)>0;return `<div class=\"card combatV3\"><div class=\"questTitle\"><h3>Combat</h3><span class=\"rarityTag\">STAMINA ${Math.floor(s.player.stamina)}</span></div><div class=\"combatant\"><div class=\"combatIcon\">${enemy.icon}</div><div class=\"grow\"><b>${enemy.name} • Lv ${enemy.level}</b><div class=\"tiny\">HP ${Math.max(0,Math.ceil(e.hp))}/${enemy.hp}</div><div class=\"bar\"><div class=\"fill hp\" style=\"width:${100*e.hp/enemy.hp}%\"></div></div></div></div><div class=\"combatBtns\"><button class=\"action primary\" data-combat=\"attack\"><b>⚔️ Attack</b><small>Reliable strike</small></button><button class=\"action\" data-combat=\"heavy\"><b>🪓 Heavy</b><small>Harder, less accurate</small></button><button class=\"action skillAction\" data-combat=\"power\"><b>💥 Power Strike</b><small>High damage • stamina</small></button><button class=\"action skillAction\" data-combat=\"precision\"><b>🎯 Precise Strike</b><small>Accurate • crit chance</small></button><button class=\"action\" data-combat=\"defend\"><b>🛡️ Defend</b><small>Reduce next hit</small></button><button class=\"action danger\" data-combat=\"flee\"><b>🏃 Flee</b><small>Attempt escape</small></button>${smoke?'<button class=\"action\" data-combat=\"smoke\"><b>💨 Vanish</b><small>Consume Smoke Bomb</small></button>':''}</div></div>`};\n","v8_2-combat-feedback":"// Combat feedback: exactly one restrained shake/jolt per player attack event.\nRF.v82CombatShake=function(){const el=document.querySelector('.battleModal');if(!el)return;el.classList.remove('singleCombatJolt');void el.offsetWidth;el.classList.add('singleCombatJolt');};\nconst v82BattleAbilityBase=RF.battleAbility;\nRF.battleAbility=function(id){const beforeHp=RF.state?.combat?.hp;const out=v82BattleAbilityBase(id);const afterHp=RF.state?.combat?.hp;if(beforeHp!=null&&afterHp!=null&&afterHp<beforeHp)requestAnimationFrame(()=>RF.v82CombatShake());return out;};\n","v10-battle-summary":"// -------- Sophisticated combat summary --------\nconst v10StartBattleBase=RF.startBattle;RF.startBattle=function(id,opts={}){let s=RF.state,e=RF.DATA.enemies[id];let out=v10StartBattleBase(id,opts);if(s?.combat){s.combat.v10Summary={enemy:id,startHp:s.player.hp,startStamina:s.player.stamina,startGold:s.gold,startXp:s.player.xp,startSkills:Object.fromEntries(['attack','strength','defence','vitality'].map(k=>[k,s.skills[k]?.xp||0])),startSkillLevels:Object.fromEntries(['attack','strength','defence'].map(k=>[k,s.skills[k]?.level||1])),startInventory:{...s.inventory},turnStart:s.combat.turn||1,damageTaken:0,parries:0,perfectParries:0};}return out};\nconst v10EnemyTurnBase=RF.enemyBattleTurn||RF.enemyTurn;if(typeof v10EnemyTurnBase==='function'){\n  let key=RF.enemyBattleTurn?'enemyBattleTurn':'enemyTurn';RF[key]=function(...a){let s=RF.state,c=s?.combat,hp=s?.player?.hp||0,logLen=c?.log?.length||0;let out=v10EnemyTurnBase.apply(this,a);if(c?.v10Summary){c.v10Summary.damageTaken+=Math.max(0,hp-(s.player.hp||0));let added=(c.log||[]).slice(logLen).join(' ');if(/PARRY/i.test(added))c.v10Summary.parries++;if(/PERFECT PARRY/i.test(added))c.v10Summary.perfectParries++;}return out};\n}\nconst v10WinBase=RF.winCombat;RF.winCombat=function(){let s=RF.state,c=s?.combat;if(!c)return;let sum=c.v10Summary?JSON.parse(JSON.stringify(c.v10Summary)):null,e=RF.DATA.enemies[c.id],turns=c.turn||1;RF.V10.deferQueue=true;try{v10WinBase()}finally{RF.V10.deferQueue=false}s=RF.state;if(!sum)return;let loot=[];Object.entries(s.inventory).forEach(([id,q])=>{let d=q-(sum.startInventory[id]||0);if(d>0&&RF.DATA.items[id])loot.push(`${RF.DATA.items[id].icon} ${RF.DATA.items[id].name} ×${d}`)});['attack','strength','defence'].forEach(k=>{let a=s.skills[k]?.level||1,b=sum.startSkillLevels?.[k]||1;if(a>b){for(let lv=b+1;lv<=a;lv++)RF.v10QueueModal({type:'v10LevelUp',kind:'skill',skill:k,level:lv})}});let skillXp=['attack','strength','defence','vitality'].map(k=>[k,(s.skills[k]?.xp||0)-(sum.startSkills[k]||0)]).filter(([,x])=>x>0);let summary={type:'v10BattleSummary',enemy:c.id,title:`${e?.name||'Enemy'} Defeated`,turns,damageTaken:sum.damageTaken,hpLeft:s.player.hp,gold:s.gold-sum.startGold,playerXp:s.player.xp-sum.startXp,skillXp,loot,parries:sum.parries,perfectParries:sum.perfectParries};RF.UI.modal=summary;RF.UI.render(s)};\n\n"};
