  const extraSources={"v7-research-combat":"// Small combat benefit for researched targets.\nconst v7BattleAbilityBase=RF.battleAbility;\nRF.battleAbility=function(id){let s=RF.state,c=s?.combat;if(c&&['attack','power','precision','bleeding_cut','crushing_blow','volley'].includes(id)){let rank=s.v7?.research?.[c.id]?.level||0;if(rank>0)c.__researchBonus=rank}return v7BattleAbilityBase(id)};\nconst v7WeaponDamageBase=RF.weaponDamage;\nRF.weaponDamage=function(s){let d=v7WeaponDamageBase(s);if(s.combat?.__researchBonus)d+=s.combat.__researchBonus;return d};\n","v9-combat-focus-core":"// ---------- Combat focus, pooled XP & parry ----------\nconst v9StartBattleBase=RF.startBattle;RF.startBattle=function(id,opts={}){let out=v9StartBattleBase(id,opts),c=RF.state?.combat;if(c){c.v9Focus=c.v9Focus||'attack';c.v9XpPool=c.v9XpPool||{attack:0,strength:0,defence:0};c.v9Parry=null}return out};\nconst v9AddXpBase=RF.addXp;RF.addXp=function(s,skill,amt){if(s?.combat?.v9XpPool&&['attack','strength','defence'].includes(skill)){let target=s.combat.v9XpForce||s.combat.v9Focus||skill;s.combat.v9XpPool[target]=(s.combat.v9XpPool[target]||0)+Math.max(0,amt);return}return v9AddXpBase(s,skill,amt)};\nRF.v9SetFocus=function(f){let s=RF.state,c=s?.combat;if(!c||c.phase!=='player'||!['attack','strength','defence'].includes(f))return;c.v9Focus=f;RF.battleLog(s,`${RF.DATA.skills[f].name} focus selected. Combat XP will bank into ${RF.DATA.skills[f].name}.`,'good');RF.save(s);RF.UI.render(s)};\nRF.v9Parry=function(){let s=RF.state,c=s?.combat;if(!c||c.phase!=='player'||!RF.combatReady())return;let def=s.skills.defence.level||1,atk=s.skills.attack.level||1;c.v9Parry={chance:Math.min(.82,.38+def*.018+atk*.004),reflect:.28+Math.min(.35,def*.012)};c.v9XpPool.defence=(c.v9XpPool.defence||0)+12;c.phase='resolving';RF.battleLog(s,'You narrow your stance and wait for the strike.','good');RF.save(s);RF.UI.render(s);setTimeout(()=>RF.enemyBattleTurn(),180)};\nconst v9EnemyTurnBase=RF.enemyBattleTurn;RF.enemyBattleTurn=function(){let s=RF.state,c=s?.combat;if(!c||!c.v9Parry)return v9EnemyTurnBase();let p=c.v9Parry;c.v9Parry=null,beforeHp=s.player.hp,buffer=5000;s.player.hp+=buffer;let out=v9EnemyTurnBase();c=s.combat;if(!c){s.player.hp=Math.min(s.player.maxHp,beforeHp);return out}let rawAfter=s.player.hp-buffer,damage=Math.max(0,beforeHp-rawAfter);s.player.hp=Math.max(1,rawAfter);if(damage>0){let success=Math.random()<p.chance;if(success){let def=s.skills.defence.level||1,perfectChance=Math.min(.32,.06+def*.009),perfect=Math.random()<perfectChance,reduction=perfect?1:(.62+Math.random()*.25);let blocked=Math.min(damage,Math.round(damage*reduction));s.player.hp=Math.min(s.player.maxHp,s.player.hp+blocked);let reflect=Math.max(1,Math.round((blocked||damage)*p.reflect+def*.35));c.hp-=reflect;s.stats.parries++;if(perfect)s.stats.perfectParries++;c.v9XpPool.defence=(c.v9XpPool.defence||0)+(perfect?10:5);c.log.unshift({text:perfect?`Perfect parry! ${blocked} damage erased and ${reflect} deflected back.`:`Parry! ${blocked} damage prevented and ${reflect} deflected back.`,type:'good'});if(c.hp<=0)return RF.winCombat()}else c.log.unshift({text:'Parry mistimed. The strike lands cleanly.',type:'bad'})}if(s.player.hp<=0)return RF.loseV4Battle();RF.save(s);RF.UI.render(s);return out};\nconst v9WinBase=RF.winCombat;RF.winCombat=function(){let s=RF.state,c=s?.combat;if(!c)return;let pool={...(c.v9XpPool||{})};v9WinBase();s=RF.state;Object.entries(pool).forEach(([sk,xp])=>{if(xp>0)v9AddXpBase(s,sk,Math.round(xp))});let txt=Object.entries(pool).filter(([,x])=>x>0).map(([sk,x])=>`${RF.DATA.skills[sk].name} +${Math.round(x)} XP`).join(' • ');if(txt)RF.log(s,`Combat training awarded on victory: ${txt}.`,'important');RF.save(s);RF.UI.render(s)};\nconst v9LoseBase=RF.loseV4Battle;RF.loseV4Battle=function(){let s=RF.state,c=s?.combat,pool=c?.v9XpPool||{};v9LoseBase();Object.entries(pool).forEach(([sk,xp])=>{if(xp>0)v9AddXpBase(RF.state,sk,Math.round(xp*.25))});RF.log(RF.state,'Defeat preserves only 25% of banked Attack/Strength/Defence training.','bad');RF.save(RF.state)};\n","v9-combat-focus-ui":"const v9CombatPopupBase=RF.UI.combatPopup.bind(RF.UI);RF.UI.combatPopup=function(s){let h=v9CombatPopupBase(s),c=s.combat;if(!c)return h;let focus=c.v9Focus||'attack',pool=c.v9XpPool||{attack:0,strength:0,defence:0};let panel=`<div class=\"combatFocus\"><span class=\"eyebrow\">COMBAT TRAINING</span><div class=\"focusBtns\">${['attack','strength','defence'].map(f=>`<button data-combat-focus=\"${f}\" class=\"${focus===f?'active':''}\" ${c.phase!=='player'?'disabled':''}>${RF.DATA.skills[f].icon} ${RF.DATA.skills[f].name}<small>Banked ${Math.round(pool[f]||0)} XP</small></button>`).join('')}</div><div class=\"sub\">Training XP is banked during battle and awarded when you win. Losing keeps only 25%.</div></div><button class=\"abilityBtn parryBtn\" data-parry ${c.phase!=='player'||(c.v8CooldownUntil||0)>Date.now()?'disabled':''}><span>🛡️</span><b>Parry</b><small>Defence training • Chance to prevent damage and deflect part of the strike.</small></button>`;return h.replace('<div class=\"battleSectionTitle\">Choose a move</div>',panel+'<div class=\"battleSectionTitle\">Choose a move</div>')};\n"};
